import json
rows=[json.loads(l) for l in open('logs/host_memory.jsonl')]
t0=rows[0]['time']
G=2**30
def parse(s): 
    d={}
    for line in s.strip().splitlines():
        k,v=line.split(); d[k]=int(v)
    return d
def st(r,k): return parse(r['cgroup']['memory.stat']).get(k,0)/G
def ev(r,k): return parse(r['cgroup']['memory.events']).get(k,0)
prev=set()
for r in rows:
    pids={p['pid'] for p in r['processes']}
    new=pids-prev; gone=prev-pids
    if new or gone:
        names={p['pid']:p['name'][:40] for p in r['processes']}
        print(f't={r[\"time\"]-t0:6.1f} cur={int(r[\"cgroup\"][\"memory.current\"])/G:5.2f} anon={st(r,\"anon\"):5.2f} shmem={st(r,\"shmem\"):5.2f} new={[ (p,names.get(p)) for p in sorted(new)]} gone={sorted(gone)}')
    prev=pids
print()
for r in rows[-14:]:
    c=r['cgroup']; s=parse(c['memory.stat'])
    print(f't={r[\"time\"]-t0:6.2f} cur={int(c[\"memory.current\"])/G:6.3f} anon={s[\"anon\"]/G:5.2f} file={s[\"file\"]/G:5.2f} shmem={s[\"shmem\"]/G:5.2f} inact_file={s.get(\"inactive_file\",0)/G:5.2f} act_file={s.get(\"active_file\",0)/G:5.2f} dirty={s.get(\"file_dirty\",0)/2**20:5.0f}MiB wb={s.get(\"file_writeback\",0)/2**20:4.0f}MiB max_ev={ev(r,\"max\")} pgsteal={s.get(\"pgsteal\",0)} w1125={[round(p[\"rss\"]/G,2) for p in r[\"processes\"] if p[\"pid\"]==1125]}')
"

